      'description' => 'खतरनाक तापक्रम क्षेत्र, पकाउने र चिस्याउने लक्ष्यहरू, मिति लेबलिङ र दैनिक खाद्य सुरक्षा अभिलेखहरू। यो कोर्स सिफ्टमा वास्तवमै गरिने प्रक्रियाको आधारमा तयार गरिएको छ, जसमा लिखित मापदण्ड, सामान्य गल्तीहरू र क्रमशः पूरा गर्नुपर्ने चेकलिस्ट समावेश छन्।',
