      'outcomes' => 
      array (
        0 => 'सुपरिवेक्षण बिना लिखित मापदण्ड अनुसार प्रक्रिया पूरा गर्नुहोस्।',
        1 => 'यस कार्यमा हुने सामान्य त्रुटिहरू पहिचान गरी सुधार गर्नुहोस्।',
