  'pages' => 
  array (
    'home' => 
    array (
      'title' => 'Hospitality Academy: साउदी अरबमा होटल कर्मचारी तालिम',
      'subtitle' => 'रियादस्थित Altus Advisory द्वारा होटल टोलीका लागि भूमिकामा आधारित तालिम, व्यावहारिक मूल्याङ्कन र प्रमाणित गर्न सकिने प्रमाणपत्र। अरबी, अंग्रेजी र तपाईंका कर्मचारीले बोल्ने भाषाहरूमा।',
      'body' => '<h2>Hospitality Academy के हो?</h2><p>Hospitality Academy साउदी अरबको रियादमा आधारित हस्पिटालिटी तथा व्यावसायिक रणनीति फर्म Altus Advisory को सार्वजनिक तालिम एकेडेमी हो। यो altus Hospitality Knowledge &amp; Performance प्लेटफर्ममा चल्छ, जसले पदअनुसार होटल कर्मचारी तालिम दिन्छ र त्यसपछि हरेक व्यक्तिले वास्तवमै काम गर्न सक्छ कि सक्दैन भनेर जाँच्छ।</p><h2>यो सामान्य अनलाइन कोर्सभन्दा कसरी फरक छ?</h2><p>कोर्स पूरा गर्नुलाई प्रमाण मानिँदैन। हरेक सिकारु भूमिकामा आधारित सिकाइबाट सैद्धान्तिक र व्यावहारिक मूल्याङ्कनतर्फ अघि बढ्छ, र नतिजा परिभाषित दक्षताहरूअनुसार रेकर्ड गरिन्छ। खाडल देखिएमा कार्ययोजना र पुनर्मूल्याङ्कन हुन्छ, जसले गर्दा म्यानेजरहरूले सकिएका भिडियोहरूको सूची होइन, क्षमताको प्रमाण देख्छन्।</p><ol><li>पदका आवश्यकताअनुसार तोकिएको सिकाइ</li><li>एउटै मापदण्डमा सैद्धान्तिक मूल्याङ्कन र व्यावहारिक मूल्याङ्कन</li><li>दक्षता अभिलेख, पहिचान गरिएका खाडल र सुधारात्मक कार्ययोजना</li><li>पुनर्मूल्याङ्कन, तयारीको स्थिति र प्रमाणित गर्न सकिने प्रमाणपत्र</li></ol><h2>एकेडेमीले होटलका कुन विभागहरू समेट्छ?</h2><p>मुख्य पाठ्यक्रम दस मुख्य व्यावसायिक क्षेत्रमा व्यवस्थित छ: होटलका आधारभूत कुरा, फ्रन्ट अफिस, हाउसकिपिङ, खाना तथा पेय, किचन, बिक्री तथा मार्केटिङ, राजस्व तथा रिजर्भेसन, पाहुना अनुभव, गुणस्तर तथा अडिट, र सुरक्षा तथा संरक्षा। <a href="/en/courses">कोर्स क्याटलग</a> हेर्नुहोस् वा कुनै खास पदका लागि संरचित <a href="/en/learning-paths">सिकाइ पथ</a> पछ्याउनुहोस्।</p><h2>होटल कर्मचारीले कुन भाषाहरूमा सिक्न सक्छन्?</h2><p>अरबी र अंग्रेजी एउटै अनुभवका रूपमा निर्मित छन्, अरबी दायाँबाट बायाँ लेआउटमा। कर्मचारी कार्यक्षेत्रले हिन्दी, उर्दू, फिलिपिनो, बंगाली, नेपाली र मलयालम पनि समर्थन गर्छ, जसले गर्दा हरेक सिफ्टमा सेवा दिने मानिसहरूले मापदण्ड बुझ्छन्।</p><h2>के रोजगारदाताले प्रमाणपत्र जाँच्न सक्छन्?</h2><p>सक्छन्। हरेक प्रमाणपत्रमा अद्वितीय नम्बर र प्रमाणीकरण कोड हुन्छ, र जो कोहीले <a href="/en/verify">प्रमाणपत्र प्रमाणीकरण पेज</a> मा यो मान्य, म्याद सकिएको वा रद्द गरिएको हो भनेर पुष्टि गर्न सक्छन्।</p><h2>एकेडेमीले Vision 2030 लाई कसरी सहयोग गर्छ?</h2><p>Vision 2030 ले 2030 सम्म राज्यमा वार्षिक 150 मिलियन भ्रमणको लक्ष्य राखेको छ र साउदी मानव पुँजीलाई त्यो वृद्धिको केन्द्रमा राखेको छ। Altus Advisory ले द्विभाषी सिकाइ पथ, मूल्याङ्कन गरिएको दक्षता र साउदी अरब तथा GCC का होटलहरूले भरोसा गर्न सक्ने प्रमाणीकरणमार्फत एकेडेमीलाई ती लक्ष्यहरूसँग मिलाउँछ।</p><p>होटल मालिक र सञ्चालकहरूले <a href="/en/hotels">आफ्ना प्रोपर्टीहरूका लागि तालिम सेटअप गर्न</a> वा <a href="/en/contact">रियादस्थित एकेडेमी टोलीसँग कुरा गर्न</a> सक्छन्।</p>',
      'cta_label' => 'कोर्स क्याटलग हेर्नुहोस्',
      'meta_title' => 'साउदी अरबमा होटल कर्मचारी तालिम | Hospitality Academy',
      'meta_description' => 'Altus Advisory द्वारा साउदी अरबमा होटल कर्मचारी तालिम: भूमिकामा आधारित सिकाइ, व्यावहारिक मूल्याङ्कन र अरबी तथा अंग्रेजीमा प्रमाणित गर्न सकिने प्रमाणपत्र।',
      'focus_keyword' => 'साउदी अरबमा होटल कर्मचारी तालिम',
    ),
    'about' => 
    array (
      'title' => 'Hospitality Academy बारे',
      'subtitle' => 'रियादस्थित Altus Advisory को सार्वजनिक तालिम एकेडेमी: सामग्रीको पछाडि को छ, यो कसरी स्वीकृत हुन्छ, र हामी के दाबी गर्छौँ र के गर्दैनौँ।',
      'body' => '<h2>Hospitality Academy कसले चलाउँछ?</h2><p>Hospitality Academy साउदी अरब राज्यको रियादमा मुख्यालय रहेको र GCC तथा MENA भरका ग्राहकलाई सेवा दिने बुटिक रणनीति फर्म Altus Advisory द्वारा सञ्चालित छ। Altus दुई एकीकृत डिभिजन, Hospitality Solutions र Business Growth Solutions मार्फत काम गर्छ, र एकेडेमी यसका सञ्चालन मापदण्डहरू होटल टोलीसम्म सिधै पुग्ने माध्यम हो।</p><h2>तालिम सामग्री कुन अनुभवमा आधारित छ?</h2><p>सामग्री Altus का संस्थापकहरूको सञ्चालन मापदण्डमा आधारित छ, जसको संयुक्त नेतृत्व अनुभव 60 वर्षभन्दा बढी छ र Marriott, IHG, Starwood र Accor प्रणालीहरू तथा स्वतन्त्र होटलहरूभित्र प्राप्त गरिएको हो। तालिम सामान्य कोर्स पुस्तकालयबाट होइन, सिफ्टमा वास्तवमै गरिने मानक सञ्चालन प्रक्रियाहरूबाट सुरु हुन्छ।</p><h2>एकेडेमी altus प्लेटफर्मसँग कसरी सम्बन्धित छ?</h2><p>एकेडेमी altus Hospitality Knowledge &amp; Performance प्लेटफर्मको सार्वजनिक प्रवेशद्वार हो। प्लेटफर्मभित्र होटलहरूले पदअनुसार सिकाइ तोक्छन्, सैद्धान्तिक र व्यावहारिक मूल्याङ्कन चलाउँछन्, दक्षताका खाडल र कार्ययोजनाहरू ट्र्याक गर्छन्, र हरेक कर्मचारीको तयारी देख्छन्। नियन्त्रित AI सहायकले स्वीकृत सामग्रीबाट मात्र कर्मचारीका प्रश्नको उत्तर दिन्छ र त्यो सामग्रीले प्रश्न नसमेटेमा त्यसै भन्छ।</p><h2>तालिम सामग्री कसरी स्वीकृत हुन्छ?</h2><p>हरेक पाठ, प्रक्रिया र मूल्याङ्कन सिकारुले देख्नुअघि नियन्त्रित समीक्षाबाट पार हुन्छ।</p><ol><li>लेखकले मस्यौदा तयार गर्छन्।</li><li>मस्यौदाले आन्तरिक स्वीकृति पाउँछ।</li><li>मस्यौदाले गुणस्तर स्वीकृति पाउँछ।</li><li>सामग्री प्रकाशित हुन्छ र यसको संस्करण रेकर्ड गरिन्छ।</li></ol><p>लेखकले आफ्नै काम स्वीकृत गर्न सक्दैनन्, र अघिल्ला संस्करणहरू अभिलेखमा रहन्छन्, जसले गर्दा अडिटरले कुनै पनि मितिमा कुन मापदण्ड लागू थियो भनेर देख्न सक्छन्।</p><h2>एकेडेमीलाई कुन सिद्धान्तहरूले मार्गदर्शन गर्छन्?</h2><p>एकेडेमीले Altus Advisory ले हरेक कार्यादेशमा लागू गर्ने सिद्धान्तहरू पालना गर्छ।</p><ul><li>अनुमानभन्दा प्रमाण: क्षमता उपस्थितिबाट मानिँदैन, मूल्याङ्कनबाट देखाइन्छ।</li><li>अरबी, अंग्रेजी र होटल कर्मचारीले प्रयोग गर्ने कार्यबलका भाषाहरूमा, हरेक सिफ्टमा टिक्ने मापदण्डहरू।</li><li>कार्यादेशभन्दा परको साझेदारी: सम्झौता सकिएपछि पनि ज्ञान ग्राहक संस्थाभित्रै रहन्छ।</li><li>साउदीकरण र युवा सशक्तीकरणका लागि Vision 2030 का लक्ष्यअनुरूप साउदी मानव पुँजीलाई सहयोग।</li></ul><h2>एकेडेमीले के दाबी गर्दैन?</h2><p>यो साइटले कुनै उत्तीर्ण दर, ग्राहकको समर्थन वा मान्यताका दाबी प्रकाशित गर्दैन। प्रमाणपत्रले ठ्याक्कै आफूले रेकर्ड गरेको कुरा बताउँछ: कसले कुन कोर्स वा कार्यक्रम, कुन मितिमा, कस्तो नतिजासहित पूरा गरे, र यो अझै मान्य छ कि छैन। <a href="/en/certificates">प्रमाणीकरण कसरी काम गर्छ</a> पढ्नुहोस्, वा <a href="/en/altus">Altus Advisory र यसका सेवाहरू</a> बारे थप जान्नुहोस्।</p>',
      'cta_label' => 'प्रमाणीकरण कसरी काम गर्छ हेर्नुहोस्',
      'meta_title' => 'रियादमा हस्पिटालिटी तालिम एकेडेमी | Altus Advisory',
      'meta_description' => 'Hospitality Academy रियादमा आधारित Altus Advisory को हस्पिटालिटी तालिम एकेडेमी हो, जुन सञ्चालक-स्तरका मापदण्ड र नियन्त्रित समीक्षामा निर्मित छ।',
      'focus_keyword' => 'रियादमा हस्पिटालिटी तालिम एकेडेमी',
    ),
    'for-hotels' => 
    array (
      'title' => 'साउदी अरबका प्रोपर्टीहरूका लागि होटल तालिम प्लेटफर्म',
      'subtitle' => 'पदअनुसार सिकाइ तोक्नुहोस्, सिद्धान्त र अभ्यासको मूल्याङ्कन गर्नुहोस्, दक्षताका खाडल बन्द गर्नुहोस् र हरेक प्रोपर्टीको तयारी एउटै द्विभाषी कार्यक्षेत्रमा हेर्नुहोस्।',
      'body' => '<h2>होटलहरूलाई कोर्स पूरा भएको मात्र होइन, क्षमताको प्रमाण किन चाहिन्छ?</h2><p>अधिकांश होटलहरूलाई आफ्ना टोलीले के गर्नुपर्छ भन्ने थाहा छ। कठिनाइ भनेको हरेक व्यक्तिले हालको मापदण्डअनुसार त्यो गर्न सक्छ भनेर प्रमाणित गर्नु, र पाहुना, अडिट वा निरीक्षणले भेट्नुअघि नै खाडलहरू पत्ता लगाउनु हो। Altus Advisory ले रियाद र साउदी अरबभरका होटलहरूका लागि यो खाडल बन्द गर्न altus Hospitality Knowledge &amp; Performance प्लेटफर्म बनाएको हो।</p><h2>होटलले प्लेटफर्मबाट के पाउँछ?</h2><p>एउटै कार्यक्षेत्र, जहाँ हरेक प्रोपर्टीका लागि तालिम, मूल्याङ्कन र प्रमाण सँगै रहन्छन्।</p><ul><li>व्यक्ति, पद, विभाग वा समूहलाई म्याद र छुटसहित तोकिएको सिकाइ</li><li>भारित रुब्रिकमा अङ्क दिइने सैद्धान्तिक र व्यावहारिक मूल्याङ्कन, जहाँ महत्त्वपूर्ण मापदण्डले नतिजाको सीमा तोक्छ</li><li>दक्षता प्रोफाइल, खाडलको हिटम्याप, प्रमाण अपलोडसहितका कार्ययोजना र पुनर्मूल्याङ्कन</li><li>प्रि-ओपनिङ टोलीका लागि ओपनिङ तयारीसहित हरेक कर्मचारीको तयारी स्थिति</li><li>गुणस्तर अडिट, KPI र CSV तथा XLSX मा निर्यात गरिने प्रतिवेदनहरू</li><li>तपाईंका स्वीकृत SOP र नीतिहरूबाट मात्र, सन्दर्भसहित उत्तर दिने नियन्त्रित AI सहायक</li><li>प्रोपर्टी ब्रान्डिङ: तपाईंको लोगो, रङ र नाम</li></ul><h2>प्लेटफर्मभित्र कसले के देख्छ?</h2><p>पहुँच तपाईंको संस्थाको संरचनाअनुसार हुन्छ। विभाग प्रमुखले आफ्नो टोली देख्छन्, जनरल म्यानेजरले प्रोपर्टी देख्छन्, र कार्यकारीले पोर्टफोलियोको सिंहावलोकन र छाप्न मिल्ने बोर्ड प्रतिवेदन देख्छन्। हरेक चरण तपाईंको संस्थाभित्र सीमित हुन्छ र अडिट लगमा रेकर्ड गरिन्छ, र कुनै पनि संस्थाले अर्को संस्थाको डेटा देख्न सक्दैन।</p><h2>प्लेटफर्म कुन प्रोपर्टीहरूका लागि डिजाइन गरिएको हो?</h2><p>Altus Advisory को कर्पोरेट प्रोफाइलअनुसार, प्लेटफर्म विश्वव्यापी चेनका प्रणालीहरूको लागत र जटिलताबिना व्यावहारिक, मापदण्डमा आधारित तालिम चाहिने साउदी अरब र अरब क्षेत्रभरका स्वतन्त्र होटल, सर्भिस्ड अपार्टमेन्ट र SME प्रतिष्ठानहरूका लागि विशेष रूपमा बनाइएको हो। आवश्यकता बढ्दो छ: साउदी पर्यटन मन्त्रालयको प्रारम्भिक तथ्याङ्कले 2025 मा 122 मिलियन आन्तरिक तथा अन्तर्राष्ट्रिय भ्रमण रेकर्ड गरेको छ, र Vision 2030 ले 2030 सम्म वार्षिक 150 मिलियन भ्रमणको लक्ष्य राखेको छ।</p><h2>हामी कसरी सुरु गर्ने?</h2><p>सेटअप खाली क्याटलगबाट होइन, तपाईंको संरचनाबाट सुरु हुन्छ।</p><ol><li>आफ्ना प्रोपर्टी, विभाग र प्रति विभाग अनुमानित कर्मचारी संख्या साझा गर्नुहोस्।</li><li>Altus ले संस्था सेटअप गर्छ र पदहरूलाई तिनलाई चाहिने दक्षताहरूसँग जोड्छ।</li><li>अनिवार्य तालिम तोकिन्छ, जसले गर्दा कर्मचारीले पहिलो लगइनमै आफ्नो सूची खोल्छन्।</li><li>म्यानेजरहरूले आफ्नो ड्यासबोर्डबाट पूरा भएको अवस्था, मूल्याङ्कन नतिजा र तयारी पछ्याउँछन्।</li></ol><p><a href="/en/hotels/training">विभागअनुसार तालिम कार्यक्रमहरू</a> हेर्नुहोस्, <a href="/en/programs">प्रमाणीकरण कार्यक्रमहरू</a> हेर्नुहोस्, वा <a href="/en/contact">एकेडेमी टोलीसँग कुरा गर्नुहोस्</a>।</p>',
      'cta_label' => 'एकेडेमीसँग कुरा गर्नुहोस्',
      'meta_title' => 'साउदी अरबमा होटल तालिम प्लेटफर्म | Altus Advisory',
      'meta_description' => 'साउदी अरबका लागि होटल तालिम प्लेटफर्म: पदअनुसार सिकाइ तोक्नुहोस्, व्यावहारिक मूल्याङ्कन चलाउनुहोस्, दक्षताका खाडल बन्द गर्नुहोस् र प्रोपर्टीअनुसार तयारी ट्र्याक गर्नुहोस्।',
      'focus_keyword' => 'साउदी अरबमा होटल तालिम प्लेटफर्म',
    ),
    'hotels-training' => 
    array (
      'title' => 'विभागअनुसार होटल कर्मचारी तालिम कार्यक्रमहरू',
      'subtitle' => 'होटलको हरेक विभागलाई केमा तालिम दिइन्छ, कुन क्रममा दिइन्छ, र कर्मचारीले सुपरिवेक्षणबिना काम गर्नुअघि क्षमता कसरी पुष्टि गरिन्छ।',
      'body' => '<h2>होटलको हरेक विभागलाई कस्तो तालिम चाहिन्छ?</h2><p>हरेक विभागले Altus Advisory ले रियादमा क्षेत्रमा परीक्षण गरिएका सञ्चालन मापदण्डबाट विकास गरेको मुख्य पाठ्यक्रमभित्र आफ्नै ट्र्याक पछ्याउँछ। सामग्री व्यावसायिक क्षेत्र, ट्र्याक, मोड्युल र पाठका रूपमा संरचित छ, त्यसपछि मूल्याङ्कन र प्रमाणीकरण हुन्छ, जसले गर्दा हरेक पदको परिभाषित पथ हुन्छ।</p><ul><li><strong>फ्रन्ट अफिस:</strong> आगमन र प्रस्थान, पाहुना दर्ता र गोपनीयता, रुम एसाइनमेन्ट, गुनासो व्यवस्थापन, अपसेलिङ र नाइट अडिट।</li><li><strong>हाउसकिपिङ:</strong> कोठा सफाइको क्रम, बेड र बाथरुमका मापदण्ड, रसायन सुरक्षा, हराएका र भेटिएका सामान, लन्ड्री, सार्वजनिक क्षेत्र र निरीक्षण।</li><li><strong>खाना तथा पेय:</strong> सेवाको क्रम, स्वागत र बसाइ व्यवस्था, टेबल र पेय सेवा, ब्याङ्क्वेट र पोइन्ट अफ सेल प्रक्रिया।</li><li><strong>किचन:</strong> खाद्य सुरक्षा, तापक्रम नियन्त्रण, भण्डारण र सामान प्राप्ति, एलर्जेन व्यवस्थापन, चक्कु सुरक्षा र फोहोर नियन्त्रण।</li><li><strong>बिक्री, राजस्व र रिजर्भेसन:</strong> बिक्री तथा मार्केटिङ, रिजर्भेसन प्रक्रिया, वितरण र राजस्वका आधारभूत कुरा।</li><li><strong>पाहुना अनुभव, गुणस्तर र अडिट:</strong> सेवा सुधार, ब्रान्ड र SOP अनुपालन, र गुणस्तर निरीक्षण।</li><li><strong>सुरक्षा तथा संरक्षा:</strong> हरेक कर्मचारीका लागि आगलागी सुरक्षा, आपतकालीन प्रतिक्रिया र सुरक्षा प्रक्रिया।</li></ul><h2>होटल कर्मचारी तालिम कुन क्रममा दिइन्छ?</h2><p>पहिले सुरक्षा र आधारभूत कुरा, त्यसपछि पदसम्बन्धी सीप, अनि उही मापदण्डको मूल्याङ्कन।</p><ol><li>हरेक कर्मचारीका लागि होटलका आधारभूत कुरा, प्रोपर्टी इन्डक्सन र सुरक्षा</li><li>पदका पूर्वशर्तहरू, जस्तै हाउसकिपिङमा रसायन सुरक्षा वा किचनमा खाद्य सुरक्षा र एलर्जेन व्यवस्थापन</li><li>भिडियो, PDF, स्लाइड वा अडियोमा छोटा व्यावहारिक पाठसहितका पदसम्बन्धी मोड्युलहरू</li><li>सैद्धान्तिक मूल्याङ्कन, त्यसपछि सुपरभाइजरद्वारा व्यावहारिक मूल्याङ्कन</li><li>प्रमाणपत्र, वा खाडल भेटिएमा कार्ययोजना र पुनर्मूल्याङ्कन</li></ol><h2>के तालिमले हाम्रै होटलका मापदण्ड पछ्याउन सक्छ?</h2><p>सक्छ। प्लेटफर्म हरेक प्रोपर्टीका लागि व्हाइट-लेबल हो, र तपाईंका स्वीकृत SOP, नीति र चेकलिस्टहरू पाठ्यक्रमसँगै रहन्छन्, हरेक संस्करणविरुद्ध कर्मचारीको स्वीकृति रेकर्ड गरिन्छ। AI सहायकले त्यही स्वीकृत सामग्रीबाट मात्र कर्मचारीका प्रश्नको उत्तर दिन्छ।</p><h2>के अरबी वा अंग्रेजी नपढ्ने कर्मचारीका लागि तालिम उपलब्ध छ?</h2><p>पाठहरू अरबी र अंग्रेजीमा द्विभाषी छन्, र साउदी अरबभरका होटलमा काम गर्ने बहुराष्ट्रिय टोलीका लागि कर्मचारी कार्यक्षेत्रले हिन्दी, उर्दू, फिलिपिनो, बंगाली, नेपाली र मलयालम पनि समर्थन गर्छ।</p><p><a href="/en/courses">पूरा कोर्स क्याटलग</a> हेर्नुहोस्, <a href="/en/learning-paths">पदअनुसार सिकाइ पथ</a> पछ्याउनुहोस्, वा <a href="/en/hotels">होटलहरूले प्लेटफर्म कसरी लागू गर्छन्</a> पढ्नुहोस्।</p>',
      'cta_label' => 'पूरा क्याटलग हेर्नुहोस्',
      'meta_title' => 'विभागअनुसार होटल कर्मचारी तालिम कार्यक्रम | KSA',
      'meta_description' => 'फ्रन्ट अफिसदेखि किचनसम्म विभागअनुसार होटल कर्मचारी तालिम कार्यक्रम, साउदी अरबका टोलीका लागि व्यावहारिक मूल्याङ्कन र प्रमाणीकरणसहित।',
      'focus_keyword' => 'होटल कर्मचारी तालिम कार्यक्रम',
