    'certificates-info' => 
    array (
      'title' => 'होटल तालिम प्रमाणपत्र र प्रमाणीकरण',
      'subtitle' => 'Hospitality Academy को प्रमाणपत्रले के रेकर्ड गर्छ, यो कहिले जारी हुन्छ, र रोजगारदाताले यो वास्तविक र हालसम्म मान्य छ कि छैन भनेर केही सेकेन्डमै कसरी जाँच्न सक्छन्।',
      'body' => '<h2>Hospitality Academy को प्रमाणपत्र कहिले जारी हुन्छ?</h2><p>सिकारुले कोर्सका सबै अनिवार्य पाठहरू पूरा गरी त्यस कोर्सका लागि तोकिएको उत्तीर्णाङ्क वा सोभन्दा बढी ल्याएर मूल्याङ्कन उत्तीर्ण गरेपछि प्रमाणपत्र जारी हुन्छ। कार्यक्रमका सबै कोर्स पूरा भएपछि कार्यक्रम प्रमाणपत्र जारी हुन्छ। प्रमाणीकरण उपस्थिति होइन, मूल्याङ्कन गरिएको क्षमता झल्काउने गरी डिजाइन गरिएको हो।</p><h2>होटल तालिम प्रमाणपत्रले के रेकर्ड गर्छ?</h2><p>हरेक प्रमाणपत्रले रोजगारदातालाई चाहिने तथ्यहरू मात्र रेकर्ड गर्छ, योभन्दा बढी होइन।</p><ul><li>सिकारुको नाम</li><li>पूरा गरिएको कोर्स वा कार्यक्रम</li><li>पूरा भएको मिति र अन्तिम अङ्क</li><li>अद्वितीय प्रमाणपत्र नम्बर, प्रमाणीकरण कोड र QR कोड</li><li>सुरक्षा र खाद्य सुरक्षा जस्ता आवधिक नवीकरण चाहिने विषयमा म्याद सकिने मिति</li></ul><h2>होटल तालिम प्रमाणपत्र कसरी प्रमाणित गर्ने?</h2><p>सार्वजनिक प्रमाणीकरण पेज प्रयोग गर्नुहोस्। कुनै खाता आवश्यक पर्दैन।</p><ol><li><a href="/en/verify">प्रमाणपत्र प्रमाणीकरण पेज</a> खोल्नुहोस्।</li><li>प्रमाणपत्रमा छापिएको प्रमाणीकरण कोड हाल्नुहोस्, वा यसको QR कोड स्क्यान गर्नुहोस्।</li><li>देखाइएको स्थिति पढ्नुहोस्: मान्य, म्याद सकिएको, रद्द गरिएको वा फेला नपरेको।</li></ol><p>मान्य नतिजाले सिकारुको नाम, विषय र जारी मिति देखाउँछ, व्यक्तिबारे अरू केही देखाउँदैन।</p><h2>प्रमाणपत्र किन रद्द गरिएको देखिन सक्छ?</h2><p>प्रमाणपत्र गल्तीले जारी भएमा, यसको आधार रहेको मूल्याङ्कन नतिजा अमान्य पाइएमा, वा जारी गर्ने संस्थाको अनुरोधमा रद्द गरिन्छ। रद्द गरिएको प्रमाणपत्र हराउँदैन, प्रमाणीकरणयोग्य रहन्छ र रद्द स्थिति देखाइरहन्छ, जसले गर्दा पुरानो प्रतिलाई हालको भनेर देखाउन सकिँदैन।</p><h2>प्रमाणपत्रहरू कसले जारी गर्छ?</h2><p>प्रमाणपत्रहरू साउदी अरबको रियादस्थित Altus Advisory द्वारा सञ्चालित altus Hospitality Knowledge &amp; Performance प्लेटफर्ममार्फत जारी हुन्छन्। प्रमाणपत्रले कुनै खास व्यक्तिले कुनै खास मितिमा कुनै खास कोर्स वा कार्यक्रम पूरा गरेको रेकर्ड गर्छ। यो इजाजतपत्र, नियामक स्वीकृति वा धारक कुनै खास पदका लागि योग्य छन् भन्ने कथन होइन।</p><p>उपलब्ध <a href="/en/programs">प्रमाणीकरण कार्यक्रमहरू</a> हेर्नुहोस् वा आफ्ना होटल कर्मचारीको प्रमाणीकरणबारे <a href="/en/contact">एकेडेमी टोलीलाई सोध्नुहोस्</a>।</p>',
      'cta_label' => 'प्रमाणपत्र प्रमाणित गर्नुहोस्',
      'meta_title' => 'होटल तालिम प्रमाणपत्र प्रमाणित गर्नुहोस् | Hospitality Academy',
      'meta_description' => 'Hospitality Academy को होटल तालिम प्रमाणपत्र कोड वा QR बाट प्रमाणित गर्नुहोस्, र प्रमाणपत्रले के रेकर्ड गर्छ, म्याद कहिले सकिन्छ र किन रद्द हुन सक्छ हेर्नुहोस्।',
      'focus_keyword' => 'होटल तालिम प्रमाणपत्र प्रमाणीकरण',
