    'contact' => 
    array (
      'title' => 'Hospitality Academy लाई सम्पर्क गर्नुहोस्',
      'subtitle' => 'आफ्ना प्रोपर्टी र टोलीबारे बताउनुहोस्, हामी ब्रोसर होइन, एउटा संरचनासहित जवाफ दिनेछौँ।',
      'body' => '<h2>आफ्नो प्रोपर्टीका लागि होटल तालिम कसरी अनुरोध गर्ने?</h2><p>रियाद वा राज्यका अन्य ठाउँमा होटल तालिमबारे आफ्नो सोधपुछ यस पेजको फारममार्फत पठाउनुहोस्। साउदी अरब राज्यको रियादस्थित Altus Advisory को Hospitality Academy टोलीका एक सदस्यले कल मिलाउन जवाफ दिनुहुनेछ। कुनै स्वचालित इमेल शृङ्खला हुँदैन, र तपाईंको विवरण कुनै तेस्रो पक्षलाई दिइँदैन।</p><h2>सोधपुछमा के समावेश गर्ने?</h2><p>केही तथ्यहरूले हामीलाई सामान्य प्रस्तुतिको सट्टा काम गर्ने संरचनासहित जवाफ दिन मद्दत गर्छन्।</p><ul><li>सम्बन्धित प्रोपर्टी र सहरहरू</li><li>तपाईं सुरु गर्न चाहनुहुने विभागहरू</li><li>हरेक विभागका अनुमानित कर्मचारी संख्या</li><li>तपाईंका कर्मचारीलाई चाहिने भाषाहरू: अरबी, अंग्रेजी, वा हिन्दी, उर्दू, फिलिपिनो, बंगाली, नेपाली वा मलयालम जस्ता कार्यबलका भाषाहरू</li><li>प्रि-ओपनिङ वा निरीक्षण जस्ता कुनै म्याद</li></ul><h2>सम्पर्क गरेपछि के हुन्छ?</h2><p>प्रक्रिया छोटो छ र स्वचालनले होइन, मानिसहरूले सम्हाल्छन्।</p><ol><li>हामी परिचयात्मक कल मिलाउन जवाफ दिन्छौँ।</li><li>हामी तपाईंका प्रोपर्टी, पद र हालका मापदण्डबारे छलफल गर्छौँ।</li><li>हामी तपाईंको टोलीका लागि विभाग, पद र अनिवार्य तालिमको संरचना प्रस्ताव गर्छौँ।</li></ol><h2>के तालिमबाहेक अन्य विषयमा Altus Advisory लाई सम्पर्क गर्न सकिन्छ?</h2><p>सकिन्छ। Altus Advisory ले साउदी अरब र GCC का होटल मालिक र लगानीकर्तालाई होटल विकास र मालिक प्रतिनिधित्व, प्रि-ओपनिङ सहयोग, सञ्चालन, पाहुना अनुभव, व्यावसायिक प्रदर्शन र फराकिलो व्यावसायिक वृद्धिमा पनि परामर्श दिन्छ। <a href="/en/altus">Altus Advisory र यसका सेवाहरू</a> बारे पढ्नुहोस्।</p><h2>प्रमाणपत्रसम्बन्धी प्रश्न लिएर कहाँ जाने?</h2><p>प्रमाणपत्र वास्तविक हो कि होइन भनेर पुष्टि गर्न सिधै <a href="/en/verify">प्रमाणपत्र प्रमाणीकरण पेज</a> प्रयोग गर्नुहोस्; कुनै सोधपुछ आवश्यक छैन। आफ्नो सिकाइ अभिलेखको प्रति वा त्यसमा सुधार अनुरोध गर्न आफ्नो रोजगारदाताको प्रशासकलाई सम्पर्क गर्नुहोस् वा यस पेजमार्फत हामीलाई लेख्नुहोस्।</p><p>लेख्नुअघि, <a href="/en/hotels">होटलहरूका लागि प्लेटफर्म कसरी काम गर्छ</a> हेर्नु वा <a href="/en/courses">कोर्स क्याटलग</a> हेर्नु उपयोगी हुन सक्छ।</p>',
      'cta_label' => 'आफ्नो सोधपुछ पठाउनुहोस्',
      'meta_title' => 'सम्पर्क: रियादमा होटल तालिम | Altus Advisory',
      'meta_description' => 'रियाद र साउदी अरबभर होटल तालिमबारे Altus Advisory को Hospitality Academy लाई सम्पर्क गर्नुहोस्। आफ्ना प्रोपर्टी, विभाग र म्याद बताउनुहोस्।',
      'focus_keyword' => 'रियादमा होटल तालिम',
