      'title' => 'गोपनीयता नीति',
      'subtitle' => 'एकेडेमीले के भण्डारण गर्छ, किन गर्छ, कसले देख्न सक्छ र कति समय राखिन्छ।',
      'body' => '<h2>यो नीति कसलाई लागू हुन्छ</h2><p>यो नीति साउदी अरब राज्यको रियादस्थित Altus Advisory द्वारा सञ्चालित तालिम एकेडेमी Hospitality Academy, र यसलाई आफ्नो रोजगारदातामार्फत वा सिधै प्रयोग गर्ने सिकारुहरूमा लागू हुन्छ।</p><h2>के सङ्कलन गरिन्छ</h2><p>सिकारुका लागि एकेडेमीले यी भण्डारण गर्छ:</p><ul><li>नाम, कार्यालयको इमेल र दिइएको भए मोबाइल नम्बर</li><li>रोजगारदाता, प्रोपर्टी, विभाग र पद</li><li>सिकाइ अभिलेख: भर्ना, पाठको प्रगति, मूल्याङ्कन प्रयास र अङ्क, प्रमाणपत्र र प्रक्रिया स्वीकृतिहरू</li></ul><h2>किन सङ्कलन गरिन्छ</h2><p>जानकारी यसका लागि प्रयोग गरिन्छ:</p><ul><li>तालिम प्रदान गर्न</li><li>तालिम पूरा भयो कि भएन रेकर्ड गर्न</li><li>प्रमाणपत्र जारी र प्रमाणित गर्न</li><li>रोजगारदातालाई आफ्नै कार्यबलको अनुपालन स्थिति हेर्न दिन</li></ul><p>केही पनि बेचिँदैन, र केही पनि विज्ञापनका लागि प्रयोग गरिँदैन।</p><h2>प्रक्रिया स्वीकृतिहरू</h2><p>स्वीकृतिले प्रयोगकर्ता, प्रक्रियाको ठ्याक्कै संस्करण, समय र स्रोत नेटवर्क ठेगाना रेकर्ड गर्छ। यो जानाजानी गरिएको हो: व्यक्ति, संस्करण र समयसँग जोड्न नसकिने स्वीकृति कुनै कुराको प्रमाण होइन।</p><h2>सिकाइ अभिलेख कसले देख्न सक्छ</h2><p>सिकाइ अभिलेख यिनले देख्न सक्छन्:</p><ul><li>सिकारु</li><li>सिकारुको लाइन म्यानेजर</li><li>उही संस्थाभित्रका विभाग, प्रोपर्टी र संस्था प्रशासकहरू</li><li>एकेडेमी प्रशासक</li></ul><p>कुनै पनि संस्थाले अर्को संस्थाको डेटा देख्न सक्दैन।</p><h2>अभिलेख राख्ने अवधि</h2><p>सिकाइ अभिलेख र प्रमाणपत्रहरू खाता सक्रिय रहुन्जेल, र त्यसपछि जारी गर्ने संस्थालाई अडिटका लागि आवश्यक परेसम्म राखिन्छन्। प्रमाणीकरणले काम गरिरहोस् भनेर प्रमाणपत्रको अभिलेख अनिश्चितकालसम्म राखिन्छ।</p><h2>तपाईंका अनुरोधहरू</h2><p>सिकारुले आफ्नो रोजगारदाताको प्रशासकमार्फत वा <a href="/en/contact">सम्पर्क पेज</a> मार्फत सिधै एकेडेमीलाई सम्पर्क गरेर आफ्नो अभिलेखको प्रति वा त्यसमा सुधार अनुरोध गर्न सक्छन्। <a href="/en/terms">प्रयोगका सर्तहरू</a> ले खाता र प्रमाणपत्रसम्बन्धी नियमहरू तोक्छन्।</p>',
      'cta_label' => 'एकेडेमीलाई सम्पर्क गर्नुहोस्',
      'meta_title' => 'गोपनीयता नीति | Altus Advisory को Hospitality Academy',
      'meta_description' => 'Hospitality Academy गोपनीयता नीति: सिकारुको कुन डेटा किन सङ्कलन गरिन्छ, सिकाइ अभिलेख कसले देख्न सक्छ, र अभिलेख तथा प्रमाणपत्र कति समय राखिन्छन्।',
      'focus_keyword' => 'गोपनीयता नीति',
