    'terms' => 
    array (
      'title' => 'प्रयोगका सर्तहरू',
      'subtitle' => 'एकेडेमी प्रयोग गर्दा र यसले जारी गर्ने प्रमाणपत्रहरूमा लागू हुने सर्तहरू।',
      'body' => '<h2>दायरा</h2><p>यी सर्तहरू साउदी अरब राज्यको रियादस्थित Altus Advisory द्वारा सञ्चालित Hospitality Academy, र यसमार्फत जारी हुने प्रमाणपत्रहरूमा लागू हुन्छन्।</p><h2>खाताहरू</h2><p>एउटा खाता नाम उल्लेखित एक व्यक्तिको हुन्छ।</p><ul><li>खाता साझा गर्न अनुमति छैन।</li><li>अर्को व्यक्तिको तर्फबाट तालिम पूरा गर्न अनुमति छैन।</li></ul><p>यी मध्ये कुनै पनि अभ्यासले त्यसबाट प्राप्त कुनै पनि प्रमाणपत्र अमान्य बनाउँछ र खाता निलम्बनको आधार हुन्छ।</p><h2>मूल्याङ्कनहरू</h2><p>मूल्याङ्कन प्रयासहरू समय र प्रयास नम्बरसहित रेकर्ड गरिन्छन्। प्रयासको सीमा, समय सीमा र प्रश्नको अनियमित क्रम हरेक मूल्याङ्कनका लागि तोकिएअनुसार लागू हुन्छन्। ती नियन्त्रणहरू छलेर प्राप्त नतिजा अमान्य हुन्छ।</p><h2>प्रमाणपत्रहरू</h2><p>प्रमाणपत्रले कुनै खास व्यक्तिले कुनै खास मितिमा कुनै खास कोर्स वा कार्यक्रम पूरा गरेको रेकर्ड गर्छ। यो इजाजतपत्र, नियामक स्वीकृति, वा धारक कुनै खास पदका लागि योग्य छन् भन्ने कथन होइन। यस्तो कुनै पनि प्रयोग यी सर्तहरूभन्दा बाहिर हो। प्रमाणपत्रको स्थिति <a href="/en/verify">प्रमाणीकरण पेज</a> मा जाँच्न सकिन्छ।</p><h2>सामग्री</h2><p>एकेडेमीले प्रकाशित गरेका कोर्स सामग्री र प्रक्रियाहरू एकेडेमी वा तिनलाई लेख्ने संस्थाको सम्पत्ति रहन्छन्। कुनै संस्थाले अपलोड गरेका प्रक्रियाहरू त्यही संस्थाको सम्पत्ति रहन्छन् र अरू कुनै संस्थासँग साझा गरिँदैनन्।</p><h2>उपलब्धता</h2><p>एकेडेमीले सेवा निरन्तर उपलब्ध राख्ने लक्ष्य राख्छ तर अवरोधरहित पहुँचको ग्यारेन्टी गर्दैन। पहुँचमा अवरोध आउने अपेक्षा भएमा योजनाबद्ध मर्मतसम्भारको पूर्वसूचना दिइन्छ।</p><h2>सम्बन्धित नीतिहरू</h2><p>व्यक्तिगत डेटा कसरी सम्हालिन्छ भन्ने कुरा <a href="/en/privacy">गोपनीयता नीति</a> मा वर्णन गरिएको छ।</p>',
      'cta_label' => 'गोपनीयता नीति पढ्नुहोस्',
