    array (
      'title' => 'नयाँ फ्रन्ट डेस्क एजेन्टलाई पहिलो दुई हप्तामा कसरी तालिम दिने',
      'excerpt' => 'होटललाई सुरक्षित राख्ने सुरक्षा र गोपनीयता तालिम नछुटाई नयाँ फ्रन्ट अफिस एजेन्टलाई सुपरिवेक्षणबिनाको सिफ्टसम्म पुर्‍याउने दुई हप्ताको क्रम।',
      'body' => '<p>नयाँ फ्रन्ट डेस्क एजेन्टलाई प्रायः धेरै चाँडो वा धेरै ढिलो सिफ्टमा राखिन्छ। धेरै चाँडो राखे मापदण्ड सिक्नुअघि नै होटलका नराम्रा बानी सिक्छन्। धेरै ढिलो राखे जिम्मेवारीबिना दुई हप्ता अरूलाई हेरेर बिताउँछन्, जसले निकै थोरै सिकाउँछ। निश्चित दुई हप्ताको क्रमले दुवैबाट बचाउँछ।</p><h2>पहिलो र दोस्रो दिन: डेस्क होइन, प्रोपर्टी</h2><p>आपतकालीन निकास, भेला हुने स्थान, उनीहरूको म्यानेजर को हो, लकर कहाँ छ, र रिपोर्टिङ लाइनहरू। आगलागी सुरक्षा र आपतकालीन प्रतिक्रिया पहिलो दिनमै सातौँ दिनको म्याद राखेर तोकिन्छ, किनभने पाहुनालाई सिँढीसम्म देखाउन नसक्ने एजेन्ट, जतिसुकै राम्रो चेक-इन गरे पनि, जोखिम हो।</p><h2>तेस्रोदेखि पाँचौँ दिन: क्रम</h2><p>फ्रन्ट अफिसका आधारभूत कुराहरू, टेलिफोन शिष्टाचार, त्यसपछि चेक-इन र चेक-आउट छुट्टाछुट्टै कोर्सका रूपमा। एजेन्टले आगमनको पूरा लहर र प्रस्थानको पूरा लहर नजिकबाट हेर्छ, र हेर्ने मात्र नभई अनुभवी एजेन्टसँगै चेकलिस्ट चलाउँछ।</p><h2>छैटौँदेखि आठौँ दिन: प्रणाली र अभिलेख</h2><p>प्रोपर्टी म्यानेजमेन्ट सिस्टम तालिम, पाहुना दर्ता र पाहुनाको गोपनीयता। गोपनीयता पछि सोच्ने कुरा होइन: कोठा नम्बरको अनुशासन, फोन गर्नेलाई के बताउन सकिन्छ, र परिचयपत्र कसरी सम्हालिन्छ भन्ने सबै कुरा एजेन्टले सुपरिवेक्षणबिना प्रणालीमा पहुँच पाउनुअघि नै सिक्छ।</p><h2>नवौँदेखि एघारौँ दिन: सुपरिवेक्षणमा</h2><p>एजेन्टले सुपरभाइजर उपस्थित भएर पनि आवश्यक नपरे हस्तक्षेप नगर्ने अवस्थामा डेस्कमा काम गर्छ। हरेक अपवाद, पहिलो कठिन पाहुना र पहिलो प्रणाली त्रुटि अर्को कोर्सभन्दा बढी मूल्यवान हुन्छन्।</p><h2>बाह्रौँदेखि चौधौँ दिन: मूल्याङ्कन र जिम्मेवारी हस्तान्तरण</h2><p>मूल्याङ्कनहरू पूरा गर्नुहोस्, सुपरभाइजरसँग चेकलिस्टका नतिजा समीक्षा गर्नुहोस्, र अनिवार्य तालिम पूरा भएको अभिलेख भएको पुष्टि गर्नुहोस्। सुपरिवेक्षणबिनाको सिफ्टमा पठाउने कुरा पर्याप्त समय बितेको अनुमान होइन, कर्मचारीको नाममा अभिलेख गरिएको, कसैको नाम जोडिएको निर्णय हो।</p><h2>त्यसपछि के आउँछ</h2><p>दोस्रो महिनामा रुम एसाइनमेन्ट, गुनासो व्यवस्थापन र अपसेलिङ, र दिनको क्रम स्वचालित भएपछि मात्र नाइट अडिट।</p>',
    ),
    'writing-a-hotel-sop-people-actually-follow' => 
    array (
      'title' => 'मानिसहरूले साँच्चै पालना गर्ने होटल SOP लेख्ने तरिका',
      'excerpt' => 'अधिकांश होटल प्रक्रियाहरू उही चार कारणले असफल हुन्छन्। कागजात प्रकाशित हुनुअघि नै हरेक कारण सुधार्न सकिन्छ।',
      'body' => '<p>अधिकांश होटलसँग प्रक्रियाहरू छन्। तर सिफ्टमा हुने कामलाई वास्तवमै बदल्ने प्रक्रियाहरू धेरै कम होटलसँग छन्। यो खाडल लगभग सधैँ लेखाइमा हुन्छ, टोलीमा होइन।</p><h2>यसले चरणहरूको सट्टा नतिजा वर्णन गर्छ</h2><p>"कोठा आवश्यक मापदण्ड अनुरूप भएको सुनिश्चित गर्नुहोस्" प्रक्रिया होइन। "बाथरुम यो क्रममा सफा गर्नुहोस्: ऐना, बेसिन, बाथ वा सावर, अन्त्यमा ट्वाइलेट, त्यसपछि भुइँ" प्रक्रिया हो। यदि कुनै वाक्य कार्यान्वयन गर्न सकिँदैन भने त्यो प्रक्रियामा होइन, गुणस्तर मापदण्ड खण्डमा पर्छ।</p><h2>यसमा एस्केलेसन मार्ग छैन</h2><p>हरेक प्रक्रियाले कहिलेकाहीँ अनपेक्षित अवस्था भेट्छ, प्रायः सबैभन्दा नराम्रो समयमा। तोकिएको एस्केलेसन मार्गबिनाको प्रक्रियाले कर्मचारीलाई आफैँ मार्ग बनाउन बाध्य पार्छ, र त्यसरी बनाइएको मार्गले नै घटना प्रतिवेदन जन्माउँछ। कसलाई, केका लागि र कति छिटो फोन गर्ने भनेर स्पष्ट लेख्नुहोस्।</p><h2>कसैलाई थाहा छैन उनले कुन संस्करण पढे</h2><p>साझा फोल्डरमा रहेको मिति नभएको प्रक्रिया प्रमाणित गर्न सकिँदैन। हरेक प्रक्रियालाई संस्करण नम्बर, लेखक, स्वीकृतकर्ता, लागू मिति र समीक्षा मिति दिनुहोस्, अघिल्ला संस्करणहरू पढ्न मिल्ने राख्नुहोस्, र हरेक नयाँ संस्करणको स्वीकृति मानिसहरूसँग माग्नुहोस्। त्यसपछि म्यानेजरले अडिटका बेला महत्त्वपूर्ण एउटै प्रश्नको जवाफ दिन सक्छन्: लागू रहेको संस्करण कसले पढेका थिए।</p><h2>यो काम नगर्ने व्यक्तिले लेखेको हो</h2><p>अफिसमा लेखेर विभागलाई थमाइएको प्रक्रियामा प्रायः विभागले छोड्न नसक्ने कुनै चरण छुटेको हुन्छ। काम गर्ने मानिसहरूसँगै मस्यौदा लेख्नुहोस्, एक पटक उनीहरूसँग व्यवहारमै दोहोर्‍याउनुहोस्, र पहिलो असफलतापछि होइन, प्रकाशनअघि नै सच्याउनुहोस्।</p><h2>प्रकाशनअघिको परीक्षण</h2><p>मस्यौदा त्यो काम कहिल्यै नगरेको व्यक्तिलाई दिनुहोस् र ठ्याक्कै पालना गर्न भन्नुहोस्। उनले सोध्ने हरेक प्रश्न एउटा छुटेको चरण हो।</p>',
    ),
    'hotel-food-safety-records-that-survive-an-inspection' => 
    array (
      'title' => 'निरीक्षणमा टिक्ने होटल खाद्य सुरक्षा अभिलेखहरू',
      'excerpt' => 'पूर्ण तापक्रम लग कस्तो हुन्छ, खाली कक्षहरू किन सबैभन्दा सामान्य कैफियत हुन्, र कागजपत्र होइन कारण कसरी सुधार्ने।',
      'body' => '<p>किचन वास्तवमै सुरक्षित भए पनि अभिलेखमा असफल हुन सक्छ। निरीक्षकले सुरक्षा चाखेर हेर्न सक्दैनन्, त्यसैले लग नै प्रमाण हो, र अपूर्ण लगलाई कागजपत्रको अभाव होइन, नियन्त्रणको अभाव मानिन्छ।</p><h2>पूर्ण लगमा के हुन्छ</h2><p>हरेक सिफ्टको सुरुमा क्यालिब्रेसन प्रविष्टि। चिसो र फ्रोजन भण्डारण प्रति सिफ्ट दुई पटक रेकर्ड। सेवाअघि पकाउने तापक्रम पुष्टि। हट होल्डिङ हरेक दुई घण्टामा रेकर्ड। चिस्याउने समय दुई चरणको लक्ष्यअनुसार रेकर्ड। पुनः तताउने काम एक पटक रेकर्ड। र सीमाबाहिरको हरेक रिडिङविरुद्ध नामसहित रेकर्ड गरिएको सुधारात्मक कार्य।</p><h2>कक्षहरू किन खाली रहन्छन्</h2><p>टोलीलाई वास्ता नभएर लगभग कहिल्यै होइन। प्रायः रिडिङ लिँदा शेफ उभिने ठाउँमा लग नहुनाले, प्रोब साझा भएर आवश्यक बेला उपलब्ध नहुनाले, वा सिफ्ट व्यस्त भएर पछि भर्ने सोचले। सिफ्टको अन्त्यमा सम्झनाबाट लेख्नु अभिलेख होइन, र प्रायः त्यो प्रस्टै देखिन्छ।</p><h2>कारण सुधार्ने</h2><p>रिडिङ लिइने ठाउँमै लग राख्नुहोस्। हरेक सेक्सनलाई आफ्नै प्रोब दिनुहोस्। दुई-दुई घण्टाको हट होल्डिङ जाँचलाई साझा होइन, सिफ्ट बोर्डमा तोकिएको व्यक्तिको जिम्मेवारी बनाउनुहोस्। त्यसपछि लग साप्ताहिक होइन दैनिक जाँच गर्नुहोस्, किनभने भोलिपल्ट बिहान भेटिएको खाडलको व्याख्या अझै गर्न सकिन्छ।</p><h2>तालिमको मुख्य कुरा</h2><p>लग पूरा गर्नुलाई प्रशासनिक काम होइन, दक्षताको हिस्सा मान्नुहोस्। अभिलेख नियन्त्रणकै हिस्सा हो भनेर तालिम पाएको शेफले रिडिङ लिने बेलामै लग भर्छ, जुन यो सत्य हुने एकमात्र समय हो।</p>',
    ),
    'measuring-hotel-training-completion-honestly' => 
    array (
      'title' => 'होटल तालिम पूरा भएको इमानदारीपूर्वक मापन',
      'excerpt' => 'उपस्थिति किन पूरा गर्नु होइन, पूरा भएको प्रतिशतले किन महत्त्वपूर्ण खाडल लुकाउन सक्छ, र यसको सट्टा के रिपोर्ट गर्ने।',
      'body' => '<p>तालिम प्रतिवेदनलाई राम्रो देखाउन सजिलो छ, उपयोगी बनाउन गाह्रो। धेरैजसो फरक तीन बानीले ल्याउँछन्।</p><h2>उपस्थिति पूरा गर्नु होइन</h2><p>हस्ताक्षर गरिएको उपस्थिति पानाले कोही कोठामा थिए भन्ने मात्र रेकर्ड गर्छ। उनले काम गर्न सक्छन् भन्ने रेकर्ड गर्दैन। मूल्याङ्कन नतिजासँग जोडिएको पूरा भएको अभिलेखले गर्छ। दोस्रोलाई रिपोर्ट गर्नुहोस्, र कक्षा सत्र वास्तवमै आवश्यकताको हिस्सा भएमा मात्र पहिलोलाई राख्नुहोस्।</p><h2>औसतले खाडल लुकाउँछ</h2><p>नब्बे प्रतिशत पूरा भएको प्रोपर्टी स्वस्थ सुनिन्छ, जबसम्म तपाईंले बाँकी दस प्रतिशत पूरै नाइट सिफ्ट वा गत महिनाका सबै नयाँ कर्मचारी हुन् भन्ने देख्नुहुन्न। विभाग, प्रोपर्टी र व्यक्तिअनुसार रिपोर्ट गर्नुहोस्, र म्याद नाघेको सूचीलाई प्रतिशतभन्दा माथि राख्नुहोस्, किनभने कसैले कारबाही गर्न सक्ने कुरा त्यही सूची हो।</p><h2>वैधताबिनाको पूरा गर्नु अनुपालन होइन</h2><p>सुरक्षा र खाद्य सुरक्षा तालिमको म्याद सकिन्छ। म्याद सकिएको प्रमाणपत्रलाई पूरा भएको गन्ने प्रतिवेदन कुनै प्रतिवेदन नहुनुभन्दा पनि खराब हो, किनभने यसले अनुचित विश्वास सिर्जना गर्छ। म्याद सकिन लागेका प्रमाणपत्रहरूलाई अपवाद प्रतिवेदनका रूपमा होइन, नियमित विषयका रूपमा देखाउनुहोस्।</p><h2>म्यानेजरसामु के राख्ने</h2><p>चार कुरा: अहिले कसको म्याद नाघेको छ, यो हप्ता कसको म्याद नाघ्दैछ, यो महिना कुन प्रमाणपत्रको म्याद सकिँदैछ, र कुन प्रक्रियाका हालका संस्करणहरू स्वीकृत गरिएका छैनन्। बाँकी सबै सन्दर्भ मात्र हो।</p>',
    ),
    'training-hotel-teams-in-arabic-and-english' => 
    array (
      'title' => 'होटल टोलीलाई अरबी र अंग्रेजी दुवैमा, कुनै पनि नगुमाई तालिम',
      'excerpt' => 'अनुवाद गरिएको कोर्स किन द्विभाषी कोर्स होइन, र वास्तविक द्विभाषी होटल तालिम कार्यक्रम व्यवहारमा कस्तो हुन्छ।',
      'body' => '<p>साउदी अरबका अधिकांश होटल टोलीहरू वास्तवमै द्विभाषी छन्, तर एकनासले होइन। हाउसकिपिङ फ्लोर मुख्यतः अरबीमा, फ्रन्ट डेस्क मुख्यतः अंग्रेजीमा, र किचन सिफ्टअनुसार बदलिने मिश्रणमा काम गर्न सक्छ। एउटै भाषा रोज्ने तालिम कार्यक्रमले चुपचाप टोलीको एक भागलाई बाहिर पार्छ।</p><h2>अनुवाद र लेखन एउटै कुरा होइन</h2><p>मेसिनले अनुवाद गरेको कोर्स अनुवाद गरिएकै जस्तो पढिन्छ, र अप्ठ्यारो पढिने प्रक्रियागत निर्देशन दबाबमा गलत बुझिन्छ। अरबी संस्करणलाई अरबी सामग्रीकै रूपमा, विभागले सिफ्टमा वास्तवमै प्रयोग गर्ने शब्दहरूसहित लेख्नुहोस्, र अंग्रेजी संस्करणलाई अंग्रेजी सामग्रीकै रूपमा। शब्दशः होइन, अर्थमा मेल खाने राख्नुहोस्।</p><h2>दायाँबाट बायाँ लेआउट हो, केवल पाठको दिशा होइन</h2><p>अरबी पेज भनेको पाठ उल्टाइएको अंग्रेजी पेज होइन। नेभिगेसन, प्रगति सूचक, चेकलिस्ट, तालिका र फारमका फिल्डहरू सबै दायाँबाट स्वाभाविक रूपमा पढिनुपर्छ। अरबी इन्टरफेसमा बायाँबाट दायाँ चल्ने क्रमबद्ध प्रक्रियामा मानिसहरूले चरणको क्रम गलत पढ्छन्।</p><h2>सिकारुलाई हरेक सत्रमा रोज्न दिनुहोस्</h2><p>भाषा साइनअपमा एक पटक तय गरिने खाता सेटिङ होइन, हरेक सत्रको छनोट हुनुपर्छ। सिकारुले सुरक्षा कोर्स अरबीमा र प्रोपर्टी म्यानेजमेन्ट सिस्टम कोर्स अंग्रेजीमा लिन सक्छन्, किनभने प्रणाली आफैँ अंग्रेजीमा छ। भाषा बदल्दा पनि प्रगति कायम रहनुपर्छ।</p><h2>अनुवाद गर्न नहुने शब्दहरू</h2><p>प्रणालीका फिल्डका नाम, रेडियोमा प्रयोग हुने कोड शब्द, र उपकरणमा छापिएको कुनै पनि शब्द कामकै भाषामा रहनुपर्छ, व्याख्या भने सिकारुको भाषामा। सिकारुले स्क्रिनमा अंग्रेजीमा देख्ने बटनको लेबल अनुवाद गर्दा खाडल बन्द हुनुको सट्टा झन् बढ्छ।</p>',
    ),
    'pre-opening-hotel-training-checklist' => 
    array (
      'title' => 'प्रि-ओपनिङ होटल तालिम: पहिलो पाहुनाअघि गरिसक्नुपर्ने कुराहरू',
      'excerpt' => 'प्रि-ओपनिङ टोलीले पछि सार्न नसक्ने तालिम र प्रक्रियाको काम, गर्नुपर्ने समयक्रम अनुसार।',
      'body' => '<p>प्रि-ओपनिङले एक वर्षको सञ्चालन तयारीलाई केही महिनामा खुम्च्याउँछ, र तालिम प्रायः पछि धकेलिन्छ किनभने भवनभन्दा कम जरुरी लाग्छ। तर यस्तो होइन, किनभने खुल्ने मिति सर्दैन तर टोलीको तयारी भने सर्छ।</p><h2>नब्बे दिन अगाडि: प्रक्रियाहरू</h2><p>प्रक्रियाहरू पालना गर्ने मानिसहरू भर्ना गर्नुअघि नै प्रक्रियाहरू लेख्नुहोस्। लिखित मापदण्ड नभएको अवस्थामा आउने विभागले आफैँ मापदण्ड बनाउँछ, र पछि त्यसलाई हटाउन अहिले लेख्नुभन्दा बढी खर्च लाग्छ। हरेक प्रक्रियालाई सुरुदेखि नै जिम्मेवार व्यक्ति, स्वीकृतकर्ता र समीक्षा मिति चाहिन्छ।</p><h2>साठी दिन अगाडि: अनिवार्य सेट</h2><p>आगलागी सुरक्षा, आपतकालीन प्रतिक्रिया र प्रोपर्टी इन्डक्सन हरेक कर्मचारीलाई ग्र्यान्ड ओपनिङअघि होइन, सफ्ट ओपनिङअघिको म्यादसहित तोकिन्छ। हाउसकिपिङले कुनै उत्पादन छुनुअघि रसायन सुरक्षा। किचनले परीक्षण सेवा चलाउनुअघि खाद्य सुरक्षा।</p><h2>तीस दिन अगाडि: विभागीय क्रम</h2><p>हरेक विभागले आफ्नो मुख्य क्रम पूरा गर्छ र आफ्ना चेकलिस्टहरू तालिम कक्षमा होइन, वास्तविक फ्लोरमा चलाउँछ। हाउसकिपिङ टोलीले पहिलो पाहुनाअघि वास्तविक भवनका वास्तविक कोठाहरू सफा गरिसकेको हुनुपर्छ, अझै तयार नभएका कोठाहरू समेत।</p><h2>चौध दिन अगाडि: ड्राइ रन</h2><p>कर्मचारीलाई पाहुना बनाएर पूरा दिनको सिमुलेसन चलाउनुहोस्: आगमन, रेस्टुरेन्ट सेवा, एउटा गुनासो, मर्मतसम्भार कल, र निकासी अभ्यास। यसले देखाउने हरेक खाडल अन्यथा पाहुनाले भेट्ने खाडल हो।</p><h2>बिक्रीमा खुला गर्नुअघि</h2><p>खुल्ने मिति जे भए पनि, आगलागी सुरक्षा, बिजुली वा पानी सुरक्षाको कुनै विषय खुला रहेको कोठा बिक्रीका लागि खुला गरिँदैन। यो निर्णय दबाब आउनुअघि नै, एक पटक, लिखित रूपमा गर्नुपर्छ।</p>',
    ),
  ),
