    array (
      'question' => 'नयाँ फ्रन्ट डेस्क एजेन्टले सबैभन्दा पहिले के सिक्नुपर्छ?',
      'answer' => 'पहिले आगलागी सुरक्षा र प्रोपर्टी इन्डक्सन, त्यसपछि फ्रन्ट अफिसका आधारभूत कुरा र टेलिफोन शिष्टाचार, त्यसपछि चेक-इन, चेक-आउट र पाहुना दर्ता, अनि प्रोपर्टी म्यानेजमेन्ट सिस्टम। आधारभूत क्रम स्वचालित भएपछि गुनासो व्यवस्थापन र नाइट अडिट आउँछन्।',
