    'topic:hotel-sop-training#11' => 
    array (
      'question' => 'होटल SOP कति पटक समीक्षा गर्नुपर्छ?',
      'answer' => 'बाह्र महिनाको समीक्षा अन्तराल सामान्य पूर्वनिर्धारित हो, र हरेक प्रक्रियाको आफ्नै समीक्षा मिति हुन्छ। प्रक्रियाले रोक्न नसकेको कुनै पनि घटनापछि, र यो निर्भर रहेको उपकरण, प्रणाली वा नियम बदलिँदा पनि तुरुन्तै समीक्षा गर्नुपर्छ।',
