    'global:#0' => 
    array (
      'question' => 'Hospitality Academy के हो?',
      'answer' => 'Hospitality Academy होटल तालिम र मानक सञ्चालन प्रक्रिया (SOP) प्लेटफर्म हो। यसले होटलका विभागहरूका लागि भूमिकामा आधारित कोर्सहरू, संस्करण व्यवस्थित SOP पुस्तकालय, मूल्याङ्कनहरू, र सार्वजनिक रूपमा प्रमाणित गर्न सकिने प्रमाणपत्रहरू प्रदान गर्छ। कोर्सहरू अरबी र अंग्रेजीमा उपलब्ध छन्।',
    ),
    'global:#1' => 
    array (
