      'answer' => 'हो। हरेक कोर्स, पाठ, प्रक्रिया र सार्वजनिक पेज अरबी र अंग्रेजीमा छुट्टाछुट्टै लेखिएको सामग्रीका रूपमा उपलब्ध छ, र अरबी इन्टरफेसले अंग्रेजीको उल्टो प्रतिबिम्ब होइन, वास्तविक दायाँबाट बायाँ लेआउट प्रयोग गर्छ।',
