    array (
      'question' => 'होटल तालिम कोर्स पूरा गर्न कति समय लाग्छ?',
      'answer' => 'अधिकांश कोर्सहरूमा पैँतालीस मिनेटदेखि तीन घण्टासम्म अध्ययन लाग्छ, र यसलाई विभिन्न सिफ्टमा बाँड्न सकिन्छ। हरेक कोर्स पेजले आफ्नो अवधि उल्लेख गर्छ, र प्रगति सुरक्षित हुन्छ जसले गर्दा सिकारुले रोकेर फेरि सुरु गर्न सक्छन्।',
