      'question' => 'के एकेडेमीले उत्तीर्ण दर वा सफलताका तथ्याङ्क प्रकाशित गर्छ?',
      'answer' => 'गर्दैन। एकेडेमीले उत्तीर्ण दर, रोजगारदाताको समर्थन वा मान्यताका दाबीहरू प्रकाशित गर्दैन, किनभने ती आगन्तुकसामु प्रमाण दिन नसकिने दाबी हुन्। प्रमाणपत्रले आफूले रेकर्ड गरेको कुरा मात्र बताउँछ: कसले, के, कहिले, कति अङ्कसहित पूरा गरे, र यो अझै मान्य छ कि छैन।',
